public class LongestIncreasingSubsequence { public static int LengthOfLIS(int[] nums) { if (nums.Length == 0) return 0; int[] dp = new int[nums.Length]; for (int i = 0; i < nums.Length; i++) { dp[i] = 1; } for (int i = 1; i < nums.Length; i++) { for (int j = 0; j < i; j++) { if (nums[i] > nums[j]) { dp[i] = Math.Max(dp[i], dp[j] + 1); } } } int max = dp[0]; for (int i = 1; i < dp.Length; i++) { if (dp[i] > max) { max = dp[i]; } } return max; } }